/* @autogenerated */
import { computed } from '@angular/core';
import { SelectionModel } from './selection-model';

describe('SelectionModel', () => {
  it('selects items and toggles selection', () => {
    const model = new SelectionModel<string>();

    model.select(['a', 'b']);
    expect(model.selected()).toEqual(['a', 'b']);

    model.toggle('c');
    expect(model.selected()).toEqual(['a', 'b', 'c']);

    model.toggle('b');
    expect(model.selected()).toEqual(['a', 'c']);
  });

  it('uses mapper when provided', () => {
    const model = new SelectionModel<{ id: number }>();
    model.modelMapper((item) => item.id);

    model.select([{ id: 1 }, { id: 2 }]);
    expect(model.isSelected({ id: 2 })).toBeTrue();

    model.toggle({ id: 2 });
    expect(model.isSelected({ id: 2 })).toBeFalse();
  });

  it('recomputes derived signals when toggling', () => {
    const model = new SelectionModel<string>();
    const hasSelection = computed(() => model.selected().length > 0);

    expect(hasSelection()).toBeFalse();
    model.toggle('a');
    expect(hasSelection()).toBeTrue();
    model.toggle('a');
    expect(hasSelection()).toBeFalse();
  });

  it('does not mutate the previous selection array', () => {
    const model = new SelectionModel<string>();
    model.select(['a']);
    const before = model.selected();

    model.toggle('b');

    expect(before).toEqual(['a']);
    expect(model.selected()).not.toBe(before);
  });

  it('stores mapped values on toggle and matches mappers that return objects', () => {
    const model = new SelectionModel<{ id: number }>();
    model.modelMapper((row) => ({ id: row.id }));

    model.toggle({ id: 1, name: 'one' });
    expect(model.selected()).toEqual([{ id: 1 }]);
    expect(model.isSelected({ id: 1, name: 'other' })).toBeTrue();

    model.toggle({ id: 1, name: 'one' });
    expect(model.selected()).toEqual([]);
  });

  it('uses a custom equality when provided', () => {
    const model = new SelectionModel<{ id: number; version: number }>();
    model.modelEquals((one, other) => one.id === other.id);

    model.select([{ id: 1, version: 1 }]);
    model.toggle({ id: 1, version: 2 });

    expect(model.selected()).toEqual([]);
  });

  it('keeps toogle as a deprecated alias of toggle', () => {
    const model = new SelectionModel<string>();
    model.toogle('a');
    expect(model.selected()).toEqual(['a']);
  });

  it('clears selection', () => {
    const model = new SelectionModel<number>();
    model.select([1, 2]);

    model.clearSelection();
    expect(model.selected()).toEqual([]);
  });
});
